/**
 * Mirrors the Cognito user pool's PasswordPolicy (infra/cognito.yaml) so the
 * Change password screen can say exactly what's wrong before a round trip.
 * Cognito still enforces the real policy; keep these two in step.
 */
export const MIN_PASSWORD_LENGTH = 12;

export const PASSWORD_RULES = `At least ${MIN_PASSWORD_LENGTH} characters, with an uppercase letter, a lowercase letter and a number.`;

export function validatePasswordChange(
  currentPassword: string,
  newPassword: string,
  confirmPassword: string,
): string | null {
  if (!currentPassword) return "Enter your current password.";
  if (newPassword !== confirmPassword) {
    return "The new passwords don’t match.";
  }
  if (newPassword === currentPassword) {
    return "The new password must be different from your current one.";
  }
  if (
    newPassword.length < MIN_PASSWORD_LENGTH ||
    !/[A-Z]/.test(newPassword) ||
    !/[a-z]/.test(newPassword) ||
    !/[0-9]/.test(newPassword)
  ) {
    return `The new password is too weak. ${PASSWORD_RULES}`;
  }
  return null;
}

lib/program-engine/plates.ts.source:
export interface PlateResult {
  /** Plates for one side of the bar, largest first. Assumes unlimited quantity of each size. */
  perSide: number[];
  /** The actual total bar weight achieved — may differ from the target if not exactly loadable. */
  achievedWeight: number;
}

const EPSILON = 1e-6;

/**
 * Computes plates-per-side for a target total weight. Greedily loads largest-first
 * without exceeding the per-side target, then checks whether adding one more of the
 * smallest available plate would land *closer* to the target (overshoot beats a bigger
 * undershoot) — e.g. target diff 7 with [5, 2.5] plates: 5+2.5=7.5 (off by 0.5) beats
 * 5 alone (off by 2).
 */
export function calculatePlates(
  targetWeight: number,
  barWeight: number,
  availablePlates: number[],
): PlateResult {
  if (targetWeight <= barWeight) {
    return { perSide: [], achievedWeight: barWeight };
  }

  const sorted = [...availablePlates].sort((a, b) => b - a);
  const perSideTarget = (targetWeight - barWeight) / 2;

  let remaining = perSideTarget;
  const used: number[] = [];

  for (const plate of sorted) {
    while (remaining >= plate - EPSILON) {
      used.push(plate);
      remaining -= plate;
    }
  }

  const smallest = sorted[sorted.length - 1];
  if (smallest !== undefined && remaining > EPSILON) {
    const undershoot = remaining;
    const overshoot = Math.abs(remaining - smallest);
    if (overshoot < undershoot) {
      used.push(smallest);
      remaining -= smallest;
    }
  }

  const achievedPerSide = perSideTarget - remaining;
  const achievedWeight =
    Math.round((barWeight + 2 * achievedPerSide) * 100) / 100;

  return {
    perSide: used.sort((a, b) => b - a),
    achievedWeight,
  };
}

lib/program-engine/progression.ts.source:
export interface LiftState {
  name: string;
  currentWeight: number;
  increment: number;
  /** Round weights (e.g. after a deload) to the nearest multiple of this. */
  roundTo: number;
  // Not strictly 5|3: Deadlift's classic program uses a single work set (1).
  setCount: number;
  /** Consecutive failed sessions on this lift, resets on any success. */
  failStreak: number;
  /** How many times this lift has been deloaded, ever. */
  deloadCount: number;
}

export interface SessionResult {
  /** true only if every set hit its target reps. */
  completed: boolean;
}

function roundToNearest(value: number, step: number): number {
  return Math.round(value / step) * step;
}

/**
 * Applies one session's result to a lift's state, producing the state to use for the
 * *next* time this lift is programmed. Rules (per prd.md #5):
 *  - full completion -> weight increases by `increment`, fail streak resets
 *  - a miss -> fail streak +1; on the 3rd consecutive miss, deload 10% and reset streak
 *  - a 2nd deload (ever) on a 5-set lift permanently drops it from 5x5 to 3x5;
 *    lifts that already run fewer than 5 sets (Deadlift's single work set)
 *    are unaffected, since the fallback is a *drop*, never a raise
 */
export function nextLiftState(
  state: LiftState,
  result: SessionResult,
): LiftState {
  if (result.completed) {
    return {
      ...state,
      currentWeight: state.currentWeight + state.increment,
      failStreak: 0,
    };
  }

  const failStreak = state.failStreak + 1;

  if (failStreak < 3) {
    return { ...state, failStreak };
  }

  const deloadCount = state.deloadCount + 1;
  const deloadedWeight = roundToNearest(
    state.currentWeight * 0.9,
    state.roundTo,
  );

  return {
    ...state,
    currentWeight: deloadedWeight,
    failStreak: 0,
    deloadCount,
    setCount: deloadCount >= 2 && state.setCount > 3 ? 3 : state.setCount,
  };
}

