import { NextResponse } from "next/server";

// Don't build redirect URLs from request.url: behind Amplify Hosting's proxy
// it reports the internal host (localhost:3000), which sends the browser to
// the wrong origin.

// Route handlers: a relative Location header keeps the browser on its host.
export function redirectTo(path: string, status: 303 | 307 = 307) {
  return new NextResponse(null, { status, headers: { Location: path } });
}

// Proxy (middleware) redirects must be absolute, so rebuild the public origin
// from the headers the hosting proxy forwards.
export function publicUrl(request: Request, path: string) {
  const internal = new URL(request.url);
  const host =
    request.headers.get("x-forwarded-host") ??
    request.headers.get("host") ??
    internal.host;
  const proto =
    request.headers.get("x-forwarded-proto") ??
    internal.protocol.replace(":", "");
  return new URL(path, `${proto}://${host}`);
}

lib/set-tap.ts.source:
import { REPS_PER_SET } from "./program-engine/workouts";

export interface SetState {
  status: "pending" | "logged";
  completed: boolean;
  actualReps: number;
}

export const PENDING_SET: SetState = {
  status: "pending",
  completed: true,
  actualReps: REPS_PER_SET,
};

// StrongLifts-style tap cycle: first tap logs a full set, each further tap
// takes a rep off (a missed set), and tapping at 0 clears the set again.
export function nextSetState(s: SetState): SetState {
  if (s.status === "pending") {
    return { status: "logged", completed: true, actualReps: REPS_PER_SET };
  }
  if (s.actualReps === 0) return PENDING_SET;
  return { status: "logged", completed: false, actualReps: s.actualReps - 1 };
}

