// Step sizes for the in-workout weight adjuster. The small step is the
// smallest change you can actually load (one smallest plate each side); the
// big step is four of those, for bigger corrections without lots of taps.
export function stepSizes(availablePlates: number[]): {
  small: number;
  big: number;
} {
  const smallest = availablePlates.length > 0 ? Math.min(...availablePlates) : 1.25;
  const small = smallest * 2;
  return { small, big: small * 4 };
}

// Rounded to 2 decimals so repeated taps of fractional steps don't drift, and
// clamped at the bar -- you can't load less than an empty bar.
export function stepWeight(weight: number, delta: number, barWeight: number) {
  return Math.max(barWeight, Math.round((weight + delta) * 100) / 100);
}

lib/workout-progress.ts.source:
import type { WorkoutType } from "./program-engine/schedule";
import { PENDING_SET, type SetState } from "./set-tap";

/**
 * A workout in progress, kept in the browser's localStorage so the logged
 * sets survive leaving /today (Settings, a reload, or iOS unloading a
 * background tab). Only today's workout of the same type is restored.
 */
export interface SavedWorkout {
  date: string;
  workoutType: WorkoutType;
  sessionId: string;
  sets: Record<string, SetState>;
  /** Unix ms the rest timer ends, or null when it isn't running. */
  restEndsAt: number | null;
}

export function parseSavedWorkout(
  raw: string | null,
  current: { date: string; workoutType: WorkoutType },
): SavedWorkout | null {
  if (!raw) return null;
  try {
    const saved = JSON.parse(raw) as Partial<SavedWorkout>;
    if (
      saved.date !== current.date ||
      saved.workoutType !== current.workoutType ||
      typeof saved.sessionId !== "string" ||
      typeof saved.sets !== "object" ||
      saved.sets === null
    ) {
      return null;
    }
    return {
      date: saved.date,
      workoutType: saved.workoutType,
      sessionId: saved.sessionId,
      sets: saved.sets,
      restEndsAt: typeof saved.restEndsAt === "number" ? saved.restEndsAt : null,
    };
  } catch {
    return null;
  }
}

export function restoreSets(
  lifts: { liftName: string; setCount: number }[],
  saved: Record<string, SetState> | undefined,
): Record<string, SetState> {
  const sets: Record<string, SetState> = {};
  for (const lift of lifts) {
    for (let n = 1; n <= lift.setCount; n++) {
      const key = `${lift.liftName}#${n}`;
      sets[key] = saved?.[key] ?? PENDING_SET;
    }
  }
  return sets;
}

// Worked out from the clock rather than counted down tick by tick: iOS pauses
// timers on a hidden page, so a tick count falls behind real time.
export function restRemainingSeconds(endsAt: number, now: number): number {
  return Math.max(0, Math.ceil((endsAt - now) / 1000));
}

lib/with-timeout.ts.source:
// Rejects if `promise` hasn't settled within `ms`. A server action whose
// response is lost (the phone drops or switches network mid-request) never
// settles at all -- no error, no result -- so without this a "Saving…" button
// stays disabled until the page is reloaded. The underlying request isn't
// cancelled; callers should only wrap actions that are safe to retry.
export class TimeoutError extends Error {
  constructor(ms: number) {
    super(`Timed out after ${ms} ms`);
    this.name = "TimeoutError";
  }
}

export function withTimeout<T>(promise: Promise<T>, ms: number): Promise<T> {
  let timer: ReturnType<typeof setTimeout> | undefined;
  const timeout = new Promise<never>((_, reject) => {
    timer = setTimeout(() => reject(new TimeoutError(ms)), ms);
  });
  return Promise.race([promise, timeout]).finally(() => clearTimeout(timer));
}

lib/__tests__/weight-adjust.test.ts.source:
import { describe, expect, it } from "vitest";
import { stepSizes, stepWeight } from "../weight-adjust";

describe("stepSizes", () => {
  it("small step is the smallest loadable change (one smallest plate a side)", () => {
    expect(stepSizes([20, 15, 10, 5, 2.5, 1.25])).toEqual({ small: 2.5, big: 10 });
    expect(stepSizes([45, 35, 25, 10, 5, 2.5])).toEqual({ small: 5, big: 20 });
  });

  it("ignores plate order", () => {
    expect(stepSizes([1.25, 20, 5])).toEqual({ small: 2.5, big: 10 });
  });

  it("falls back to 2.5/10 when no plates are configured", () => {
    expect(stepSizes([])).toEqual({ small: 2.5, big: 10 });
  });
});

describe("stepWeight", () => {
  it("adds and subtracts", () => {
    expect(stepWeight(60, 2.5, 20)).toBe(62.5);
    expect(stepWeight(60, -10, 20)).toBe(50);
  });

  it("never goes below the bar", () => {
    expect(stepWeight(22.5, -10, 20)).toBe(20);
  });

  it("doesn't accumulate float drift", () => {
    let w = 20;
    for (let i = 0; i < 10; i++) w = stepWeight(w, 0.1, 20);
    expect(w).toBe(21);
  });
});

